package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct { // 01 TAX-REC, 13 bytes
	TrId     string          // PIC X(5) @0 len=5
	TrIncome decimal.Decimal // PIC 9(6)V99 @5 len=8
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                             // PIC X len=1 = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0)       // PIC 9(7)V99 len=9 = 0
var WsNet decimal.Decimal = decimal.NewFromInt(0)       // PIC 9(7)V99 len=9 = 0
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0)  // PIC 9(9)V99 len=11 = 0
var WsCount int64 = 0                                   // PIC 9(3) len=3 = 0
var WsIncEd string // PIC ZZZ,ZZ9.99 len=10
var WsTaxEd string // PIC ZZZ,ZZ9.99 len=10
var WsNetEd string // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var taxRec TaxRec
var taxFileLines []string
var taxFileIdx int

func isInputDone() bool { return WsEofFlag == "Y" }

func formatEdited(value decimal.Decimal, picture string) string {
	// Determine scale = count of 9/Z after '.'
	scale := 0
	if dot := strings.Index(picture, "."); dot != -1 {
		for _, c := range picture[dot+1:] {
			if c == '9' || c == 'Z' {
				scale++
			}
		}
	}
	// Prepare fixed point string with exactly scale decimals, trunc toward zero is already done
	// Use formatting that keeps scale
	neg := value.IsNegative()
	if neg {
		value = value.Neg()
	}
	// Get integer and fractional parts via StringFixed
	s := value.StringFixed(int32(scale))
	// s like "1234.56" or "1234" if scale 0
	var intPartStr, fracPartStr string
	if scale > 0 {
		parts := strings.SplitN(s, ".", 2)
		intPartStr = parts[0]
		if len(parts) > 1 {
			fracPartStr = parts[1]
		}
		// ensure frac length = scale
		if len(fracPartStr) < scale {
			fracPartStr += strings.Repeat("0", scale-len(fracPartStr))
		} else if len(fracPartStr) > scale {
			fracPartStr = fracPartStr[:scale]
		}
	} else {
		intPartStr = s
		// remove sign already
		if idx := strings.Index(intPartStr, "."); idx != -1 {
			intPartStr = intPartStr[:idx]
		}
	}
	// Remove sign if present
	intPartStr = strings.TrimPrefix(intPartStr, "-")
	// Count digit positions in integer part of picture (Z and 9 before dot)
	intDigitCount := 0
	dotPos := strings.Index(picture, ".")
	var intPic string
	if dotPos != -1 {
		intPic = picture[:dotPos]
	} else {
		intPic = picture
	}
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigitCount++
		}
	}
	// Handle overflow: keep low-order digits
	if len(intPartStr) > intDigitCount {
		intPartStr = intPartStr[len(intPartStr)-intDigitCount:]
	}
	// left pad with zeros to intDigitCount
	if len(intPartStr) < intDigitCount {
		intPartStr = strings.Repeat("0", intDigitCount-len(intPartStr)) + intPartStr
	}
	// Build output array
	picRunes := []rune(picture)
	out := make([]rune, len(picRunes))
	for i, c := range picRunes {
		out[i] = c
	}
	// Map integer digits to picture digit positions
	digitIdx := 0
	// We need to know seenNonZero for comma handling
	seenNonZero := false

	// First pass to set digits and commas: iterate left to right
	for i, c := range picRunes {
		if c == 'Z' || c == '9' {
			// only integer part digits in this loop until dot; fractional handled later
			if dotPos != -1 && i > dotPos {
				break
			}
			d := rune(intPartStr[digitIdx])
			if d != '0' {
				seenNonZero = true
			}
			// decide display for this digit position
			if c == 'Z' && d == '0' && !seenNonZero {
				// Actually need to look ahead: if all remaining integer digits are zero and no non-zero seen,
				// the Z before the mandatory 9 should be space, but the 9 itself should show 0.
				// Our seenNonZero is false here, so we suppress.
				// However need to avoid suppressing if this zero is after a non-zero? But then seenNonZero true.
				out[i] = ' '
			} else {
				out[i] = d
				if c == '9' {
					// a '9' position even with '0' counts as displayed; but for comma logic after,
					// if the value is zero we still want commas suppressed. So do not set seenNonZero for zero '9'?
					// Keep seenNonZero as is for zero '9' (remains false) so commas stay spaces.
					// If digit is non-zero, seenNonZero already true.
				}
			}
			digitIdx++
		} else if c == ',' {
			if seenNonZero {
				out[i] = ','
			} else {
				out[i] = ' '
			}
		} else if c == '.' {
			out[i] = '.'
		}
	}
	// Fraction part: fill digits after dot
	if scale > 0 && dotPos != -1 {
		fracIdx := 0
		for i := dotPos + 1; i < len(picRunes); i++ {
			c := picRunes[i]
			if c == '9' || c == 'Z' {
				if fracIdx < len(fracPartStr) {
					out[i] = rune(fracPartStr[fracIdx])
				} else {
					out[i] = '0'
				}
				fracIdx++
			}
		}
	}
	// Negative sign handling not needed (all positive), but if negative insert minus
	if neg {
		// place minus at first non-space position left of number, simplified: first space -> '-'
		// Not needed for this program
		for i := len(out) - 1; i >= 0; i-- {
			if out[i] != ' ' && out[i] != ',' && out[i] != '.' {
				// find leftmost digit position to place sign
				break
			}
		}
	}
	return string(out)
}

func truncToScale(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}

func roundToScale(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Round(scale)
}

// Paragraphs

func MainPara() {
	OpenTaxFile()
	PerformReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	CloseTaxFile()
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	// DISPLAY "TAXPAYERS: " WS-COUNT " TOTAL TAX: " WS-TOTAL-ED
	fmt.Printf("TAXPAYERS: %03d TOTAL TAX: %s\n", WsCount, WsTotalEd)
}

func ReadPara() {
	PerformReadPara()
}

func PerformReadPara() {
	if taxFileIdx >= len(taxFileLines) {
		WsEofFlag = "Y"
		return
	}
	line := taxFileLines[taxFileIdx]
	taxFileIdx++
	// pad with spaces to 13
	if len(line) < 13 {
		line = line + strings.Repeat(" ", 13-len(line))
	} else if len(line) > 13 {
		line = line[:13]
	}
	// parse TR-ID @0 len5
	taxRec.TrId = line[0:5]
	// TR-INCOME @5 len8 digits 9(6)V99
	raw := line[5 : 5+8]
	raw = strings.TrimSpace(raw)
	if raw == "" {
		raw = "00000000"
	}
	// digits only; build decimal with shift -2
	// raw may contain spaces if padded; remove spaces
	raw = strings.ReplaceAll(raw, " ", "0")
	n := int64(0)
	fmt.Sscanf(raw, "%d", &n)
	// Use decimal.New with exponent -2
	taxRec.TrIncome = decimal.New(n, -2)
}

func ProcessPara() {
	// IF TR-INCOME <= 10000.00
	limit1 := decimal.NewFromInt(10000)
	limit2 := decimal.NewFromInt(40000)
	thousand := decimal.NewFromInt(1000)
	sevenThousand := decimal.NewFromInt(7000)
	tenPct := decimal.NewFromFloat(0.10)
	twentyPct := decimal.NewFromFloat(0.20)
	thirtyPct := decimal.NewFromFloat(0.30)
	tenKDec := decimal.New(1000000, -2)   // 10000.00
	fortyKDec := decimal.New(4000000, -2) // 40000.00

	if taxRec.TrIncome.Cmp(tenKDec) <= 0 {
		v := taxRec.TrIncome.Mul(tenPct)
		v = roundToScale(v, 2)
		WsTax = truncToScale(v, 2)
		// high-order truncation to 9(7)V99 -> keep low 9 digits (7 int +2 dec) ; values small ignore
	} else {
		if taxRec.TrIncome.Cmp(fortyKDec) <= 0 {
			diff := taxRec.TrIncome.Sub(tenKDec)
			v := diff.Mul(twentyPct).Add(thousand)
			v = roundToScale(v, 2)
			WsTax = truncToScale(v, 2)
		} else {
			diff := taxRec.TrIncome.Sub(fortyKDec)
			v := diff.Mul(thirtyPct).Add(sevenThousand)
			v = roundToScale(v, 2)
			WsTax = truncToScale(v, 2)
		}
	}
	_ = limit1
	_ = limit2
	_ = tenPct
	WsNet = truncToScale(taxRec.TrIncome.Sub(WsTax), 2)
	WsTotalTax = truncToScale(WsTotalTax.Add(WsTax), 2)
	WsCount++

	WsIncEd = formatEdited(taxRec.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s\n", taxRec.TrId, WsIncEd, WsTaxEd, WsNetEd)
	PerformReadPara()
}

func OpenTaxFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists treat as empty
		taxFileLines = []string{}
		return
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	// Keep line as is (without newline). Scanner strips newline.
	for sc.Scan() {
		line := sc.Text()
		// Keep as is; if empty line is record of spaces?
		taxFileLines = append(taxFileLines, line)
	}
	// handle trailing newline etc; scanner handles.
	taxFileIdx = 0
}

func CloseTaxFile() {
	// nothing
}

func main() {
	MainPara()
}
